window.__CH("c16",["<div class=\"hw\">J, j</div><div class=\"pos\"><i>indecl n</i></div><div class=\"def\">ラテン字母 I は, 本来, 母音 [i] と半母音 [j] の両方を表わした. このため, 中世に半母音 [j] のみを表わす字母として作られたのが J, j.</div>\r\n","<div class=\"hw\">jacere<SUP>2</SUP></div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://jaciō\">jacio</a>.</div>\r\n","<div class=\"hw\">Jacetānī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">ヤケターニー《Hispania 北部, Pyrene 山脈のふもとにいた一部族》.</div>\r\n","<div class=\"hw\">jaceō</div><div class=\"pos\">-ēre jacuī jacitum, <i>intr</i></div><div class=\"ori\">[<i>cf. </i> jacio]</div><div class=\"def\"><num>①</num> 横たわっている 〈in re〉.</div><div class=\"def\"><num>②</num> 休んでいる, 寝ている, 横になっている.</div><div class=\"def\"><num>③</num> 投げられている, 倒されている;死んでいる.</div><div class=\"def\"><num>④</num> とどまっている, 滞在している.</div><div class=\"def\"><num>⑤</num> (ある場所に)ある, 位置している.</div><div class=\"def\"><num>⑥</num> たれさがっている.</div><div class=\"def\"><num>⑦</num> 打ち倒されている, 卑しめられている</div><div class=\"ex\"><i>pauper ubique jacet</i> (<author>O<small>V</small></author>)<span class=\"ext\">貧乏人はどこでもおとしめられている.</span></div><div class=\"def\"><num>⑧</num> 静止している, 何もしていない</div><div class=\"ex\"><i>jacent terrae</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">土地が(耕されずに)遊んでいる.</span></div><div class=\"def\"><num>⑨</num> 意気消沈している, 落胆している.</div><div class=\"def\"><num>⑩</num> 低い, 低いところにある</div><div class=\"ex\"><i>jacent pretia praediorum</i> (<author>C<small>IC</small></author>)<span class=\"ext\">農地の値段が下がっている.</span></div>\r\n","<div class=\"hw\">jaciō</div><div class=\"pos\">-cere jēcī jactum, <i>tr</i></div><div class=\"ori\">[<i>cf. </i> ico]</div><div class=\"def\"><num>①</num> 投げる, 投げつける, 投げ捨てる 〈alqd in alqd〉</div><div class=\"ex\"><i>jacere ancoram</i> (<author>C<small>AES</small></author>)<span class=\"ext\">投錨[停泊]する</span></div><div class=\"ex\"><i>jacere semen</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">種をまく</span></div><div class=\"ex\"><i>jacere talos</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">さいころを振る.</span></div><div class=\"def\"><num>②</num> (光・熱などを)発する, 放つ.</div><div class=\"def\"><num>③</num> (非難・侮辱などを)ぶつける, 向ける.</div><div class=\"def\"><num>④</num> (ことばを)ふと漏らす, 口に出す.</div><div class=\"def\"><num>⑤</num> 置く, 据える</div><div class=\"ex\"><i>jacere fundamenta</i> (<author>L<small>IV</small></author>)<span class=\"ext\">基礎を置く, 土台を築く 〈alcis rei〉.</span></div>\r\n","<div class=\"hw\">jactans</div><div class=\"pos\">-antis, <i>adj</i>(<i>prp</i>)</div><div class=\"ori\">[jacto]</div><div class=\"def\"><num>①</num> 自慢する, 高慢な.</div><div class=\"def\"><num>②</num> 誇り高い.</div>\r\n","<div class=\"hw\">jactanter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://jactans\">jactans</a>]</div><div class=\"def\">自慢して, これ見よがしに.</div>\r\n","<div class=\"hw\">jactantia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[jactans]</div><div class=\"def\">自慢, 見せびらかし, 誇示.</div>\r\n","<div class=\"hw\">jactitō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr freq</i></div><div class=\"ori\">[↓<a href=\"entry://jactō\">jactō</a>]</div><div class=\"def\"><num>①</num> (ことばを)投げかける, (冗談を)とばす.</div><div class=\"def\"><num>②</num> 自慢する.</div>\r\n","<div class=\"hw\">jactus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://jaciō\">jacio</a>.</div><hr><div class=\"hw\">jactus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\"><num>①</num> 投げること;射程.</div><div class=\"def\"><num>②</num> 投げ落とすこと, 投げ捨てること.</div><div class=\"def\"><num>③</num> 激しい動き.</div><div class=\"def\"><num>④</num> 発すること, 放つこと.</div>\r\n","<div class=\"hw\">jactābilis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[jacto]</div><div class=\"def\">よく動く.</div>\r\n","<div class=\"hw\">jactābundus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[jacto]</div><div class=\"def\"><num>①</num> (海が)荒れ狂う.</div><div class=\"def\"><num>②</num> 自慢する.</div>\r\n","<div class=\"hw\">jactātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[jacto]</div><div class=\"def\"><num>①</num> 揺り動かすこと</div><div class=\"ex\"><i>～ corporis</i> (<author>C<small>IC</small></author>)<span class=\"ext\">身振り手振り.</span></div><div class=\"def\"><num>②</num> 自慢, 見せびらかし, 誇示.</div><div class=\"def\"><num>③</num> (心の)揺れ動き, 不安定.</div>\r\n","<div class=\"hw\">jactātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[jacto]</div><div class=\"def\">自慢家, 見せびらかし屋.</div>\r\n","<div class=\"hw\">jactātus</div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"ori\">[jacto]</div><div class=\"def\">揺り動かすこと, 震わせること.</div>\r\n","<div class=\"hw\">jactō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr freq</i></div><div class=\"ori\">[jacio]</div><div class=\"def\"><num>①</num> 投げる.</div><div class=\"def\"><num>②</num> 投げやる, 投げ捨てる.</div><div class=\"def\"><num>③</num> 無視する, はねつける.</div><div class=\"def\"><num>④</num> (光などを)発する, 放つ.</div><div class=\"def\"><num>⑤</num> 揺り動かす, 振り回す.</div><div class=\"def\"><num>⑥</num> 苦しめる, 悩ます.</div><div class=\"def\"><num>⑦</num> 強く言う, 自由に議論する</div><div class=\"ex\"><i>pluribus praesentibus res jactare</i> (<author>C<small>AES</small></author>)<span class=\"ext\">多数の前で問題を突っ込んで論ずる.</span></div><div class=\"def\"><num>⑧</num> 自慢する, 誇示する, 見せびらかす.</div>\r\n","<div class=\"hw\">jactūra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[jacio]</div><div class=\"def\"><num>①</num> 投げ捨てること.</div><div class=\"def\"><num>②</num> 犠牲, 損失</div><div class=\"ex\"><i>jacturam facere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">損害をこうむる, 失う 〈alcis rei〉.</span></div><div class=\"def\"><num>③</num> 浪費, 濫費.</div><div class=\"def\"><num>④</num> 出費, 費用.</div>\r\n","<div class=\"hw\">jaculor</div><div class=\"pos\">-ārī -ātus sum, <i>intr</i>, <i>tr dep</i></div><div class=\"ori\">[↓<a href=\"entry://jaculum\">jaculum</a>]</div><div class=\"def\"><num0>Ⅰ</num0> (<i>intr</i>)</div><div class=\"def\"><num>①</num> 槍を投げる.</div><div class=\"def\"><num>②</num> 非難する, 罵倒する.</div><div class=\"def\"><num0>Ⅱ</num0> (<i>tr</i>)</div><div class=\"def\"><num>①</num> 投げる, 投げつける 〈alqd in alqm;alqd alci rei〉.</div><div class=\"def\"><num>②</num> 射る, 射殺す.</div><div class=\"def\"><num>③</num> (光などを)放つ.</div><div class=\"def\"><num>④</num> 得ようとする, 狙う.</div><div class=\"def\"><num>⑤</num> (ことばを)発する.</div>\r\n","<div class=\"hw\">jaculum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[jacio]</div><div class=\"def\"><num>①</num> 投げ槍.</div><div class=\"def\"><num>②</num> 投網.</div>\r\n","<div class=\"hw\">jaculus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[jacio]</div><div class=\"def\">投げるための.</div><hr><div class=\"hw\">jaculus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">〘動〙ヘビの一種《木の上から獲物に跳びかかる》.</div>\r\n","<div class=\"hw\">jaculābilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[jaculor]</div><div class=\"def\">投げることのできる.</div>\r\n","<div class=\"hw\">jaculātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[jaculor]</div><div class=\"def\">投げること.</div>\r\n","<div class=\"hw\">jaculātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[jaculor]</div><div class=\"def\"><num>①</num> 投げる人.</div><div class=\"def\"><num>②</num> 槍使い;槍兵.</div>\r\n","<div class=\"hw\">jaculātrix</div><div class=\"pos\">-īcis, <i>f</i></div><div class=\"ori\">[jaculator]</div><div class=\"def\">槍使い;狩人《女性;Diana の添え名》.</div>\r\n","<div class=\"hw\">jaculātōrius</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://jaculātor\">jaculātor</a>]</div><div class=\"def\"><num>①</num> 槍投げの.</div><div class=\"def\"><num>②</num> 〘カト〙射祷の.</div>\r\n","<div class=\"hw\">jacēre<SUP>1</SUP></div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://jaceō\">jaceo</a>.</div>\r\n","<div class=\"hw\">jam</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[<i>cf. </i> is]</div><div class=\"def\"><num>①</num> すでに, もう</div><div class=\"ex\"><i>non ～</i> (<author>C<small>IC</small></author>) =<i>～non</i> (<author>L<small>IV</small></author>)<span class=\"ext\">もはや...ない.</span></div><div class=\"def\"><num>②</num> 今, 目下</div><div class=\"ex\"><i>～ nunc</i> (<author>C<small>IC</small></author>)<span class=\"ext\">たった今.</span></div><div class=\"def\"><num>③</num> ～...～ あるいは...あるいは, ある時は...ある時は</div><div class=\"ex\"><i>flumina ～ lactis</i>, <i>～ flumina nectaris ibant</i> (<author>O<small>V</small></author>)<span class=\"ext\">乳の川が流れると思えば, 蜜の川も流れた.</span></div><div class=\"def\"><num>④</num> 今まで, ずっと.</div><div class=\"def\"><num>⑤</num> 直ちに, 間もなく, やがて.</div><div class=\"def\"><num>⑥</num> (話題の移行)さて, さらに.</div><div class=\"def\"><num>⑦</num> 全く, 本当に.</div>\r\n","<div class=\"hw\">jamdiū, jam diū</div><div class=\"pos\"><i>adv</i></div><div class=\"def\">ずっと前から, すでに長らく</div><div class=\"ex\"><i>～ flebam</i> (<author>O<small>V</small></author>)<span class=\"ext\">私はずっと前から泣いていた.</span></div>\r\n","<div class=\"hw\">jamdūdum, jam dūdum</div><div class=\"pos\"><i>adv</i></div><div class=\"def\">ずっと前から, すでに長らく.</div>\r\n","<div class=\"hw\">jamjam, jam jam, jam jamque</div><div class=\"pos\"><i>adv</i></div><div class=\"def\">今にも.</div>\r\n","<div class=\"hw\">jamprīdem, jam prīdem</div><div class=\"pos\"><i>adv</i></div><div class=\"def\">ずっと前から.</div>\r\n","<div class=\"hw\">Japhet(h)</div><div class=\"pos\"><i>indecl</i><SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Heb</i>.]</div><div class=\"def\">〘聖〙ヤペテ《Noa の第3子》.</div>\r\n","<div class=\"hw\">jecur</div><div class=\"pos\">-coris [-cinoris], <i>n</i></div><div class=\"def\"><num>①</num> 肝臓.</div><div class=\"def\"><num>②</num> 感情の源.</div>\r\n","<div class=\"hw\">jecusculum</div><div class=\"pos\">-ī, <i>n dim</i></div><div class=\"ori\">[↑<a href=\"entry://jecur\">jecur</a>]</div><div class=\"def\">(小さな)肝臓.</div>\r\n","<div class=\"hw\">jentāculum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://jentō\">jentō</a>]</div><div class=\"def\">(起床直後の軽い)朝食.</div>\r\n","<div class=\"hw\">jentō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i></div><div class=\"def\">朝食を取る.</div>\r\n","<div class=\"hw\">Jerichō</div><div class=\"pos\"><i>indecl</i><SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Heb</i>.]</div><div class=\"def\">イェリコー, <SUP>∥</SUP>エリコ《Palaestina の古都》.</div>\r\n","<div class=\"hw\">jocor</div><div class=\"pos\">-ārī -ātus sum, <i>intr dep</i></div><div class=\"ori\">[jocus]</div><div class=\"def\">ふざける, 冗談を言う.</div>\r\n","<div class=\"hw\">joculanter</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[joculor]</div><div class=\"def\">冗談に, ふざけて.</div>\r\n","<div class=\"hw\">joculor</div><div class=\"pos\">-ārī -ātus sum, <i>intr dep</i></div><div class=\"ori\">[↓<a href=\"entry://joculus\">joculus</a>]</div><div class=\"def\">=<a href=\"entry://jocor\">jocor</a>.</div>\r\n","<div class=\"hw\">joculus</div><div class=\"pos\">-ī, <i>m dim</i></div><div class=\"ori\">[jocus]</div><div class=\"def\">(ちょっとした)冗談.</div>\r\n","<div class=\"hw\">joculāria</div><div class=\"pos\">-ium, <i>n pl</i></div><div class=\"ori\">[↓<a href=\"entry://joculāris\">joculāris</a>]</div><div class=\"def\">冗談, 戯れ.</div>\r\n","<div class=\"hw\">joculāris</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[joculus]</div><div class=\"def\">冗談の, ふざけた, 滑稽な.</div>\r\n","<div class=\"hw\">joculāriter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://joculāris\">joculāris</a>]</div><div class=\"def\">冗談に, ふざけて, 滑稽に.</div>\r\n","<div class=\"hw\">joculārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://joculāris\">jocularis</a>.</div>\r\n","<div class=\"hw\">joculātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[joculor]</div><div class=\"def\">冗談を言う人, おどけ者.</div>\r\n","<div class=\"hw\">joculātrix</div><div class=\"pos\">-īcis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[juculator]</div><div class=\"def\">道化, 芸人《女性》.</div>\r\n","<div class=\"hw\">joculātōrius</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://joculātor\">joculātor</a>]</div><div class=\"def\">冗談の, ふざけた.</div>\r\n","<div class=\"hw\">jocur</div><div class=\"pos\">-cineris [-cinoris], <i>n</i></div><div class=\"def\">=<a href=\"entry://jecur\">jecur</a>.</div>\r\n","<div class=\"hw\">jocus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> 冗談, ふざけること.</div><div class=\"def\"><num>②</num> 笑い草, 物笑いの種.</div><div class=\"def\"><num>③</num> くだらぬこと.</div>\r\n","<div class=\"hw\">jocābundus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[jocor]</div><div class=\"def\">冗談を言う, ふざけた.</div>\r\n","<div class=\"hw\">jocātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[jocor]</div><div class=\"def\">冗談, ふざけること.</div>\r\n","<div class=\"hw\">jocātus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://jocor\">jocor</a>.</div>\r\n","<div class=\"hw\">jocōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[jocus]</div><div class=\"def\">冗談を言う, ふざけた, ひょうきんな.</div>\r\n","<div class=\"hw\">jocōsē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://jocōsus\">jocōsus</a>]</div><div class=\"def\">冗談に, ふざけて.</div>\r\n","<div class=\"hw\">Jopē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i><<i>Heb</i>.]</div><div class=\"def\">ヨペー, <SUP>∥</SUP>ヨッパ《Palaestina の海港;現 Jaffa》.</div>\r\n","<div class=\"hw\">Jordānēs</div><div class=\"pos\">-is, <i>m</i></div><div class=\"def\">ヨルダーネース, <SUP>∥</SUP>ヨルダン川《Palaestina の川》.</div>\r\n","<div class=\"hw\">Jovis</div><div class=\"pos\"><i>gen</i></div><div class=\"def\">⇒<a href=\"entry://Juppiter\">Juppiter</a>.</div>\r\n","<div class=\"hw\">Jovius<SUP>1</SUP></div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://Jovis\">Jovis</a>]</div><div class=\"def\">Juppiter の.</div><hr><div class=\"hw\">Jovius<SUP>2</SUP></div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"def\">Diocletianus 帝の添え名.</div>\r\n","<div class=\"hw\">Joviālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[Jovis]</div><div class=\"def\">Juppiter の</div><div class=\"ex\"><i>stella ～</i> (<author>M<small>ACR</small></author>)<span class=\"ext\">木星.</span></div>\r\n","<div class=\"hw\">Joviānus<SUP>1</SUP></div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[Jovius<SUP>2</SUP>]</div><div class=\"def\">Diocletianus 帝の.</div><hr><div class=\"hw\">Joviānus<SUP>2</SUP></div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"def\">ヨウィアーヌス《ローマ皇帝(在位363‐64)》.</div>\r\n","<div class=\"hw\">Joviānī</div><div class=\"pos\">-orum, <SUP>◇</SUP><i>m pl</i></div><div class=\"ori\">[↓<a href=\"entry://Joviānus\">Joviānus<SUP>1</SUP></a>]</div><div class=\"def\">Diocletianus 帝の軍団兵たち.</div>\r\n","<div class=\"hw\">juba</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> たてがみ.</div><div class=\"def\"><num>②</num> (かぶとの)前立て.</div>\r\n","<div class=\"hw\">Juba</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">ユバ《 (1) Numidia の王;Thapsus の戦い(前46)に敗れて自殺した.(2) (1) の息子;Augustus 帝によって Mauritania の王にされた》.</div>\r\n","<div class=\"hw\">jubar</div><div class=\"pos\">-aris, <i>n</i></div><div class=\"def\"><num>①</num> 曙光.</div><div class=\"def\"><num>②</num> 光, 輝き.</div>\r\n","<div class=\"hw\">jubeō</div><div class=\"pos\">-ēre jussī jussum, <i>tr</i></div><div class=\"def\"><num>①</num> 命ずる, 指図する 〈alci alqd;+<i>acc c. inf</i>;+<i>inf</i>;ut, ne〉.</div><div class=\"def\"><num>②</num> (決議を)裁可する;(命令を)追認する.</div><div class=\"def\"><num>③</num> 任命する;割り当てる.</div><div class=\"def\"><num>④</num> 〘医〙処方する.</div><div class=\"def\"><num>⑤</num> 促す, 乞う</div><div class=\"ex\"><i>sperare nos amici jubent</i> (<author>C<small>IC</small></author>)<span class=\"ext\">友人たちは私たちに望みを持てという</span></div><div class=\"ex\"><i>Dionysium jube salvere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">Dionysius によろしく伝えてください.</span></div>\r\n","<div class=\"hw\">jubātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[juba]</div><div class=\"def\">たてがみ[冠毛]のある.</div>\r\n","<div class=\"hw\">jugis<SUP>2</SUP></div><div class=\"pos\">-etis, <i>adj</i></div><div class=\"ori\">[jungo]</div><div class=\"def\">一くびきの動物の.</div>\r\n","<div class=\"hw\">jugulum</div><div class=\"pos\">-ī, <i>n</i>, <B>jugulus</B> -ī, <i>m</i></div><div class=\"ori\">[↓<a href=\"entry://jugum\">jugum</a>]</div><div class=\"def\"><num>①</num> 鎖骨.</div><div class=\"def\"><num>②</num> のど.</div><div class=\"def\"><num>③</num> のどを切ること, 殺害.</div>\r\n","<div class=\"hw\">jugulāris</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[jugulum]</div><div class=\"def\">〘解〙頸静脈の.</div>\r\n","<div class=\"hw\">jugulātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://jugulō\">jugulō</a>]</div><div class=\"def\">(のどを切って)殺すこと.</div>\r\n","<div class=\"hw\">jugulō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://jugulum\">jugulum</a>]</div><div class=\"def\"><num>①</num> (のどを切って)殺す;虐殺する.</div><div class=\"def\"><num>②</num> 滅ぼす;だいなしにする.</div>\r\n","<div class=\"hw\">jugum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>cf. </i> jungo]</div><div class=\"def\"><num>①</num> くびき.</div><div class=\"def\"><num>②</num> 一くびきの動物;一対.</div><div class=\"def\"><num>③</num> (結婚・隷従の)きずな, 束縛.</div><div class=\"def\"><num>④</num> 横木.</div><div class=\"def\"><num>⑤</num> くびき門《捕虜が服従のあかしにくぐらされた三本槍の門》.</div><div class=\"def\"><num>⑥</num> 天秤棒.</div><div class=\"def\"><num>⑦</num> 〘天〙天秤座.</div><div class=\"def\"><num>⑧</num> 織機の巻棒.</div><div class=\"def\"><num>⑨</num> こぎ手の座席.</div><div class=\"def\"><num>⑩</num> 山脈;尾根.</div><div class=\"def\"><num>⑪</num> <SUP>◇</SUP>〘昆〙翅垂<SUB>しすい</SUB>.</div>\r\n","<div class=\"hw\">Jugurtha</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">ユグルタ《Numidia の王;ローマの将軍 Marius に征服された(前104)》.</div>\r\n","<div class=\"hw\">Jugurthīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Jugurtha の.</div>\r\n","<div class=\"hw\">jugālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[jugum]</div><div class=\"def\"><num>①</num> くびきにつながれた.</div><div class=\"def\"><num>②</num> 結婚の.</div>\r\n","<div class=\"hw\">jugālēs</div><div class=\"pos\">-ium, <i>m pl</i></div><div class=\"ori\">[↓<a href=\"entry://jugālis\">jugālis</a>]</div><div class=\"def\">一くびきの動物.</div>\r\n","<div class=\"hw\">jugārius<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[jugum]</div><div class=\"def\"><num>①</num> くびきにつながれた.</div><div class=\"def\"><num>②</num> <i>Vicus ～</i> (<author>L<small>IV</small></author>) ローマ市の中心部の大通りの一つ.</div><hr><div class=\"hw\">jugārius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">牛飼い.</div>\r\n","<div class=\"hw\">jugātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[jugo]</div><div class=\"def\">ブドウのつるを棚にからませること.</div>\r\n","<div class=\"hw\">jugātus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[jugo]</div><div class=\"def\"><num>①</num> (ブドウのつるが)棚にからませられた.</div><div class=\"def\"><num>②</num> (<i>n pl</i> の名詞として)</div><div class=\"ex\"><i>jugata(verba)</i> (<author>Q<small>UINT</small></author>)<span class=\"ext\">同一語根からの派生語.</span></div>\r\n","<div class=\"hw\">jugō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[jugum]</div><div class=\"def\"><num>①</num> つなぐ, 結びつける.</div><div class=\"def\"><num>②</num> 結婚させる.</div>\r\n","<div class=\"hw\">jugōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[jugum]</div><div class=\"def\">山地の.</div>\r\n","<div class=\"hw\">Jullus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ユッルス《ローマ人の家名》.</div>\r\n","<div class=\"hw\">junceus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[juncus]</div><div class=\"def\"><num>①</num> トウシンソウ[イグサ]のような.</div><div class=\"def\"><num>②</num> トウシンソウ[イグサ]で作った.</div>\r\n","<div class=\"hw\">junctim</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[junctus]</div><div class=\"def\"><num>①</num> いっしょに.</div><div class=\"def\"><num>②</num> 連続して, 引き続いて.</div>\r\n","<div class=\"hw\">junctiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[jungo]</div><div class=\"def\">結合, 結びつき.</div>\r\n","<div class=\"hw\">junctus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[jungo]</div><div class=\"def\"><num>①</num> 結合した.</div><div class=\"def\"><num>②</num> 隣接する.</div><div class=\"def\"><num>③</num> 親しい;血縁の</div><div class=\"ex\"><i>junctissimus illi comes</i> (<author>O<small>V</small></author>)<span class=\"ext\">彼の無二の親友.</span></div><div class=\"def\"><num>④</num> 関連した.</div><div class=\"def\"><num>⑤</num> 複合の.</div>\r\n","<div class=\"hw\">junctūra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[jungo]</div><div class=\"def\"><num>①</num> 接合点, つなぎ目.</div><div class=\"def\"><num>②</num> 結合, 連結.</div><div class=\"def\"><num>③</num> (語の)配列, 並置.</div><div class=\"def\"><num>④</num> きずな, 緑.</div><div class=\"def\"><num>⑤</num> <SUP>◇</SUP>〘解〙連結</div><div class=\"ex\"><i>juncturae ossium</i><span class=\"ext\">骨の連結</span></div><div class=\"ex\"><i>juncturae tendineum</i><span class=\"ext\">腱間結合.</span></div>\r\n","<div class=\"hw\">juncus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">〘植〙トウシンソウ, イグサ.</div>\r\n","<div class=\"hw\">juncōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[juncus]</div><div class=\"def\">トウシンソウ[イグサ]の多い.</div>\r\n","<div class=\"hw\">jungō</div><div class=\"pos\">-ere junxī junctum, <i>tr</i></div><div class=\"def\"><num>①</num> くびきをかける, 引き具をつける.</div><div class=\"def\"><num>②</num> (馬を車に)つなぐ.</div><div class=\"def\"><num>③</num> つなぐ, 接合する, 連結する 〈alqd ad alqd;alqd alci rei;alqd cum re〉</div><div class=\"ex\"><i>fluvium ponte jungere</i> (<author>L<small>IV</small></author>)<span class=\"ext\">川に橋をかける</span></div><div class=\"ex\"><i>jungere oscula</i> (<author>O<small>V</small></author>)<span class=\"ext\">接吻する.</span></div><div class=\"def\"><num>④</num> 合体させる, 一体にする</div><div class=\"ex\"><i>externus timor infensos inter se jungebat animos</i> (<author>L<small>IV</small></author>)<span class=\"ext\">外からの脅威は互いに憎み合っていた市民たちの心を一つにつないでいた.</span></div><div class=\"def\"><num>⑤</num> (関係を)結ぶ.</div><div class=\"def\"><num>⑥</num> 共同で行なう, 参加する.</div><div class=\"def\"><num>⑦</num> 連続させる.</div><div class=\"def\"><num>⑧</num> 同時に行なう.</div><div class=\"def\"><num>⑨</num> 結びつけて考える.</div><div class=\"def\"><num>⑩</num> 並べる, 並列する.</div>\r\n","<div class=\"hw\">junxī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://jungō\">jungo</a>.</div>\r\n","<div class=\"hw\">Juppiter, Jūpiter</div><div class=\"pos\">Jovis, <i>m</i></div><div class=\"def\">〘神話〙</div><div class=\"def\"><num>①</num> ユッピテル《Saturnus の息子で Juno の夫;ローマ神話の最高神;ギリシア神話の Zeus に当たる》</div><div class=\"ex\"><i>～ Stygius</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">=<a href=\"entry://Plūtō\">Pluto</a>.</span></div><div class=\"def\"><num>②</num> 《詩》天, 大気, 大空.</div><div class=\"def\"><num>③</num> 〘天〙木星.</div>\r\n","<div class=\"hw\">jurgium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://jurgō\">jurgō</a>]</div><div class=\"def\"><num>①</num> 口論, けんか.</div><div class=\"def\"><num>②</num> 悪口, 罵倒.</div><div class=\"def\"><num>③</num> 訴訟.</div>\r\n","<div class=\"hw\">jurgō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i>(<i>tr</i>)</div><div class=\"ori\">[jus<SUP>2</SUP>/ago]</div><div class=\"def\"><num>①</num> 口論する, けんかする.</div><div class=\"def\"><num>②</num> ののしる, 非難する.</div>\r\n","<div class=\"hw\">juscellum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n dim</i></div><div class=\"ori\">[↓<a href=\"entry://jusculum\">jusculum</a>]</div><div class=\"def\">スープ, ソース.</div>\r\n","<div class=\"hw\">jusculum</div><div class=\"pos\">-ī, <i>n dim</i></div><div class=\"ori\">[jus<SUP>1</SUP>]</div><div class=\"def\">スープ.</div>\r\n","<div class=\"hw\">jusjūrandum</div><div class=\"pos\">jūrisjūrandī, <i>n</i></div><div class=\"ori\">[jus<SUP>2</SUP>/juro]</div><div class=\"def\">誓い, 誓約.</div>\r\n","<div class=\"hw\">jussiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[jubeo]</div><div class=\"def\">命令.</div>\r\n","<div class=\"hw\">jussum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[jubeo]</div><div class=\"def\"><num>①</num> 命令.</div><div class=\"def\"><num>②</num> (医師の)処方.</div>\r\n","<div class=\"hw\">jussus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://jubeō\">jubeo</a>.</div><hr><div class=\"hw jl\"><SUP>*</SUP>jussus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\">(用例は <i>sg abl</i> jussū のみ)命令</div><div class=\"ex\"><i>jussū meo</i> (<author>C<small>IC</small></author>)<span class=\"ext\">私の命令によって.</span></div>\r\n","<div class=\"hw\">jussī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://jubeō\">jubeo</a>.</div>\r\n","<div class=\"hw\">jussō</div><div class=\"pos\"><i>fut pf</i></div><div class=\"def\">《古形》=jussero(⇒ <a href=\"entry://jubeō\">jubeo</a>).</div>\r\n","<div class=\"hw\">justificus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[justus / facio]</div><div class=\"def\">正義の, 公正な.</div>\r\n","<div class=\"hw\">justificātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[justifico]</div><div class=\"def\"><num>①</num> 正当化, 弁明.</div><div class=\"def\"><num>②</num> 〘神学〙義認《信仰によって義とされること》.</div>\r\n","<div class=\"hw\">justificātus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[↓<a href=\"entry://justificō\">justificō</a>]</div><div class=\"def\">義とされた.</div>\r\n","<div class=\"hw\">justificō</div><div class=\"pos\">-āre -āvī -ātum, <SUP>◇</SUP><i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://justificus\">justificus</a>]</div><div class=\"def\"><num>①</num> 正しくふるまう, 正当に取り扱う.</div><div class=\"def\"><num>②</num> 義とする, 赦す, 擁護する.</div>\r\n","<div class=\"hw\">justitia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[justus]</div><div class=\"def\">正義, 公正, 公平.</div>\r\n","<div class=\"hw\">justitium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[jus<SUP>2</SUP>/sisto]</div><div class=\"def\"><num>①</num> 裁判停止, 休廷.</div><div class=\"def\"><num>②</num> 停止, 休止.</div>\r\n","<div class=\"hw\">justum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://justus\">justus</a>]</div><div class=\"def\"><num>①</num> 公正, 正当.</div><div class=\"def\"><num>②</num> (<i>pl</i>)正当な権利.</div><div class=\"def\"><num>③</num> 正当な儀式;葬儀.</div><div class=\"def\"><num>④</num> (<i>pl</i>)正規の任務.</div>\r\n","<div class=\"hw\">justus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[jus<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> 正当な, 公正な;合法の.</div><div class=\"def\"><num>②</num> 当然与えられるべき.</div><div class=\"def\"><num>③</num> 公平な, 公明正大な.</div><div class=\"def\"><num>④</num> 適切な, 十分な, 完全な;根拠のある</div><div class=\"ex\"><i>justa inimicitia</i> (<author>C<small>IC</small></author>)<span class=\"ext\">十分に根拠のある敵意</span></div><div class=\"ex\"><i>justa stipendia</i> (<author>T<small>AC</small></author>)<span class=\"ext\">満期をつとめた兵役期間.</span></div><div class=\"def\"><num>⑤</num> (軍隊・戦闘が)正規の, 正式の.</div>\r\n","<div class=\"hw\">justē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[justus]</div><div class=\"def\"><num>①</num> 合法的に, 法にかなって.</div><div class=\"def\"><num>②</num> 正当に, 当然.</div>\r\n","<div class=\"hw\">Justīniānus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"def\">ユスティーニアーヌス(1世)《東ローマ皇帝(在位527‐65)》.</div>\r\n","<div class=\"hw\">Justīnus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"def\">ユスティーヌス《 (1) <i>～ I</i>, ローマ皇帝(在位518‐527).(2) <i>～II</i>, 東ローマ皇帝(在位565‐78).(3) ローマの史家(3世紀);Trogus Pompeius の史書の要約を作った.(4) キリスト教の護教者で聖人;ローマで殉教(165没)》.</div>\r\n","<div class=\"hw\">juvenca</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[juvencus<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> 若い雌牛.</div><div class=\"def\"><num>②</num> 少女, 若い娘.</div>\r\n","<div class=\"hw\">juvenculus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m dim</i></div><div class=\"ori\">[juvencus<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> 若い雄牛.</div><div class=\"def\"><num>②</num> 若者, 青年.</div>\r\n","<div class=\"hw\">juvencus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[juvenis<SUP>1</SUP>]</div><div class=\"def\">(動物について)若い.</div><hr><div class=\"hw\">juvencus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> 若い雄牛.</div><div class=\"def\"><num>②</num> 青年, 若者.</div>\r\n","<div class=\"hw\">juvenescō</div><div class=\"pos\">-ere juvenuī, <i>intr inch</i></div><div class=\"ori\">[juvenis<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 成長する, 大人になる.</div><div class=\"def\"><num>②</num> 若返る.</div><div class=\"def\"><num>③</num> 新芽を出す.</div>\r\n","<div class=\"hw\">juvenis<SUP>1</SUP></div><div class=\"pos\">-is, <i>adj</i>(<i>comp</i> junior [juvenior])</div><div class=\"def\">若い;若々しい.</div><hr><div class=\"hw\">juvenis<SUP>2</SUP></div><div class=\"pos\">-is, <i>m</i>(<i>f</i>)</div><div class=\"def\">青年《男女》.</div>\r\n","<div class=\"hw\">juvenix</div><div class=\"pos\">-īcis, <i>f</i></div><div class=\"def\">=<a href=\"entry://jūnix\">junix</a>.</div>\r\n","<div class=\"hw\">juvenor</div><div class=\"pos\">-ārī -ātus sum, <i>intr dep</i></div><div class=\"ori\">[juvenis<SUP>1</SUP>]</div><div class=\"def\">(青年のように)無分別にふるまう.</div>\r\n","<div class=\"hw\">juventa</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[juvenis<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 青年時代, 青春期.</div><div class=\"def\"><num>②</num> 若いこと, 若々しさ.</div><div class=\"def\"><num>③</num> (集合的に)若者たち.</div><div class=\"def\"><num>④</num> (J-)=<a href=\"entry://juventās\">juventas 2</a>.</div>\r\n","<div class=\"hw\">Juventius<SUP>1</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ユウェンティウス《ローマ人の氏族名》.</div><hr><div class=\"hw\">Juventius<SUP>2</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Juventius の.</div>\r\n","<div class=\"hw\">juventās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[juvenis<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 青年時代;若さ.</div><div class=\"def\"><num>②</num> (J-)ユウェンタース《青春の女神(=<a href=\"entry://Hēbē\">Hebe</a>)》.</div>\r\n","<div class=\"hw\">juventūs</div><div class=\"pos\">-ūtis, <i>f</i></div><div class=\"ori\">[juvenis<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 青春期, 青年時代.</div><div class=\"def\"><num>②</num> (集合的に)若者たち.</div><div class=\"def\"><num>③</num> (J-)=<a href=\"entry://juventās\">juventas 2</a>.</div>\r\n","<div class=\"hw\">juvenuī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://juvenescō\">juvenesco</a>.</div>\r\n","<div class=\"hw\">juvenālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[juvenis<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 若い;若々しい.</div><div class=\"def\"><num>②</num> 力強い, 活気のある.</div>\r\n","<div class=\"hw\">Juvenālis</div><div class=\"pos\">-is, <i>m</i></div><div class=\"def\">ユウェナーリス《<i>D. Junius ～</i>, ローマの諷刺詩人(60?‐?128)》.</div>\r\n","<div class=\"hw\">juvenāliter</div><div class=\"pos\"><i>adv</i></div><div class=\"def\">=<a href=\"entry://juvenīliter\">juveniliter</a>.</div>\r\n","<div class=\"hw\">juvenīlis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[juvenis<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 若い;若々しい.</div><div class=\"def\"><num>②</num> 活気のある.</div>\r\n","<div class=\"hw\">juvenīliter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://juvenīlis\">juvenīlis</a>]</div><div class=\"def\">若々しく, 血気盛んに, 活発に.</div>\r\n","<div class=\"hw\">juvāmen</div><div class=\"pos\">-minis, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[juvo]</div><div class=\"def\">援助, 助力.</div>\r\n","<div class=\"hw\">juvō</div><div class=\"pos\">-āre jūvī jūtum(<i>fut p</i> juvātūrus), <i>tr</i></div><div class=\"def\"><num>①</num> 助ける, 援助する, 助力する 〈alqm [alqd]〉.</div><div class=\"def\"><num>②</num> 役立つ, 有益である.</div><div class=\"def\"><num>③</num> 喜ばせる</div><div class=\"ex\">(impers)<i>juvit me tibi tuas litteras profuisse</i> (<author>C<small>IC</small></author>)<span class=\"ext\">私はあなたの学識があなたの役に立ったことを喜んだ.</span></div>\r\n","<div class=\"hw\">juxtim</div><div class=\"pos\"><i>adv</i>, <i>prep</i></div><div class=\"ori\">[↑<a href=\"entry://juxtā\">juxtā</a>]</div><div class=\"def\"><num0>Ⅰ</num0> (<i>adv</i>)すぐ近くに, 接して.</div><div class=\"def\"><num0>Ⅱ</num0> (<i>prep</i>)〈+<i>acc</i>〉 ...の隣に, ...のすぐ近くに.</div>\r\n","<div class=\"hw\">juxtā</div><div class=\"pos\"><i>adv</i>, <i>prep</i></div><div class=\"ori\">[<i>cf. </i> jungo]</div><div class=\"def\"><num0>Ⅰ</num0> (<i>adv</i>)</div><div class=\"def\"><num>①</num> 接して, すぐ近くに.</div><div class=\"def\"><num>②</num> 同様に, 等しく</div><div class=\"ex\"><i>aestatem et hiemem ～ pati</i> (<author>S<small>ALL</small></author>)<span class=\"ext\">夏の暑さにも冬の寒さにも同じようによく耐える</span></div><div class=\"ex\"><i>～ ac si hostes adessent</i> (<author>S<small>ALL</small></author>)<span class=\"ext\">あたかも敵勢が間近にせまっているかのように.</span></div><div class=\"def\"><num0>Ⅱ</num0> (<i>prep</i>)〈+<i>acc</i>〉</div><div class=\"def\"><num>①</num> ...のすぐ近くに, ...の傍らに.</div><div class=\"def\"><num>②</num> ...の直後に, ...の次に.</div><div class=\"def\"><num>③</num> ほとんど, ほぼ.</div><div class=\"def\"><num>④</num> ...と一致して, ...に従って.</div>\r\n","<div class=\"hw\">jājūnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://jējūnus\">jejunus</a>.</div>\r\n","<div class=\"hw\">Jāna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">〘神話〙ヤーナ《月の女神(=<a href=\"entry://Diāna\">Diana</a>)》.</div>\r\n","<div class=\"hw\">Jāniculum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[Janus]</div><div class=\"def\">ヤーニクルム《ローマ市の七丘に対峙する, Tiberis 川西岸の丘》.</div>\r\n","<div class=\"hw\">Jānigena</div><div class=\"pos\">-ae, <i>adj</i></div><div class=\"ori\">[Janus/gigno]</div><div class=\"def\">Janus から生まれた.</div>\r\n","<div class=\"hw\">jānitor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[janua]</div><div class=\"def\">玄関番, 門番</div><div class=\"ex\"><i>～ Orci</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">=<a href=\"entry://Cerberus\">Cerberus</a>.</span></div>\r\n","<div class=\"hw\">jānitrix</div><div class=\"pos\">-īcis, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://jānitor\">jānitor</a>]</div><div class=\"def\">玄関番, 門番《女性》.</div>\r\n","<div class=\"hw\">jānua</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[janus]</div><div class=\"def\"><num>①</num> 戸, 門, 玄関.</div><div class=\"def\"><num>②</num> 入口.</div>\r\n","<div class=\"hw\">Jānual</div><div class=\"pos\">-ālis, <i>n</i></div><div class=\"def\">Janus 神に捧げる菓子.</div>\r\n","<div class=\"hw\">jānus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> 有蓋通路, 拱廊<SUB>きょうろう</SUB>.</div><div class=\"def\"><num>②</num> (J-)〘神話〙ヤーヌス《イタリアの古い神;頭の前と後ろに顔があり, 戸口・門の守護神》.</div><div class=\"def\"><num>③</num> Janus 神殿.</div>\r\n","<div class=\"hw\">Jānuārius<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> Janus の.</div><div class=\"def\"><num>②</num> 1月の</div><div class=\"ex\"><i>Kalendae Januariae</i> (<author>V<small>ARR</small></author>)<span class=\"ext\">1月1日.</span></div><hr><div class=\"hw\">Jānuārius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">(<i>sc. </i> mensis)一月.</div>\r\n","<div class=\"hw\">Jānālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">Janus の.</div>\r\n","<div class=\"hw\">Jāsō(n)</div><div class=\"pos\">-onis, <i>m</i></div><div class=\"def\">=<a href=\"entry://Iāsō(n)\">Iason</a>.</div>\r\n","<div class=\"hw\">Jāzyges</div><div class=\"pos\">-um, <i>m pl</i></div><div class=\"def\">=<a href=\"entry://Iāzyges\">Iazyges</a>.</div>\r\n","<div class=\"hw\">jēcī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://jaciō\">jacio</a>.</div>\r\n","<div class=\"hw\">jējūnitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[jejunus]</div><div class=\"def\"><num>①</num> 絶食, 空腹.</div><div class=\"def\"><num>②</num> 欠乏, 不足.</div><div class=\"def\"><num>③</num> (文体の)貧弱, 無味乾燥.</div>\r\n","<div class=\"hw\">jējūnium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[jejunus]</div><div class=\"def\"><num>①</num> 断食, 絶食.</div><div class=\"def\"><num>②</num> 空腹, 飢餓.</div><div class=\"def\"><num>③</num> 土地がやせていること, 不毛.</div>\r\n","<div class=\"hw\">jējūnum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[↓<a href=\"entry://jējūnus\">jējūnus</a>]</div><div class=\"def\">〘解〙空腸.</div>\r\n","<div class=\"hw\">jējūnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> 断食[絶食]している;飢えている, 空腹の.</div><div class=\"def\"><num>②</num> 貧弱な, 乏しい.</div><div class=\"def\"><num>③</num> 微々たる, 取るに足らぬ.</div><div class=\"def\"><num>④</num> (文体が)無味乾燥の.</div>\r\n","<div class=\"hw\">jējūnālis</div><div class=\"pos\">-is -e, <i><SUP>◇</SUP>adj</i></div><div class=\"ori\">[jejunum]</div><div class=\"def\">〘解〙空腸の.</div>\r\n","<div class=\"hw\">jējūnē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[jejunus]</div><div class=\"def\">(文体が)貧弱に, 無味乾燥に.</div>\r\n","<div class=\"hw\">jējūnō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>intr</i></div><div class=\"ori\">[jejunus]</div><div class=\"def\"><num>①</num> 断食する 〈<i>abs</i>〉.</div><div class=\"def\"><num>②</num> 控える, 断つ 〈alci rei〉.</div>\r\n","<div class=\"hw\">Jēremiās</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Heb</i>.]</div><div class=\"def\">〘聖〙エレミヤ《ヘブライの預言者》.</div>\r\n","<div class=\"hw\">Jēsūs</div><div class=\"pos\">-ū, <SUP>◇</SUP><i>m</i></div><div class=\"def\">=<a href=\"entry://Iēsūs\">Iesus</a>.</div>\r\n","<div class=\"hw\">Jōannēs</div><div class=\"pos\">-is, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i><<i>Heb</i>.]</div><div class=\"def\">〘聖〙ヨハネ《 (1) 洗礼者ヨハネ.(2) 福音史家ヨハネ》.</div>\r\n","<div class=\"hw\">Jōb</div><div class=\"pos\"><i>indecl</i><SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Heb</i>.]</div><div class=\"def\">〘聖〙ヨブ《ヘブライの族長;忍苦・堅忍の典型》.</div>\r\n","<div class=\"hw\">Jōbus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"def\">=<a href=\"entry://Jōb\">Job</a>.</div>\r\n","<div class=\"hw\">jōcund-</div><div class=\"def\">⇒jucund-.</div>\r\n","<div class=\"hw\">jōdoformium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">〘化〙ヨードホルム.</div>\r\n","<div class=\"hw\">jōdum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">〘化〙ヨード.</div>\r\n","<div class=\"hw\">Jōhannēs</div><div class=\"pos\">-is, <SUP>◇</SUP><i>m</i></div><div class=\"def\">=<a href=\"entry://Jōannēs\">Joannes</a>.</div>\r\n","<div class=\"hw\">Jōnās</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i><<i>Heb</i>.]</div><div class=\"def\">〘聖〙ヨナ《預言者の一人》.</div>\r\n","<div class=\"hw\">Jōsēph</div><div class=\"pos\"><i>indecl</i><SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Heb</i>.]</div><div class=\"def\">〘聖〙ヨセフ《 (1) イスラエル民族の祖 Jacob の息子.(2) 聖母 Maria の夫》.</div>\r\n","<div class=\"hw\">Jōsūe</div><div class=\"pos\"><i>indecl</i><SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Heb</i>.]</div><div class=\"def\">〘聖〙ヨシュア《Moyses の後継者でイスラエル民族の指導者》.</div>\r\n","<div class=\"hw\">jūbilaeus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i><<i>Heb. </i>]</div><div class=\"def\"><num>①</num> 〘聖〙ヨベルの年《ユダヤ民族がカナンへ入ってから50年ごとの年;この年には奴隷の解放, 借金の帳消しなどを神が Moyses に命じた》.</div><div class=\"def\"><num>②</num> 〘カト〙聖年, 特赦の年.</div>\r\n","<div class=\"hw\">jūbilum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↑<a href=\"entry://jūbilō\">jūbilō</a>]</div><div class=\"def\">叫び声;(羊飼いの)歌声.</div>\r\n","<div class=\"hw\">jūbilātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[jubilo]</div><div class=\"def\"><num>①</num> 叫ぶこと.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 陽気な歌声.</div>\r\n","<div class=\"hw\">jūbilātus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://jūbilō\">jubilo</a>.</div><hr><div class=\"hw\">jūbilātus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\">歓喜.</div>\r\n","<div class=\"hw\">jūbilō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i>, <i>tr</i></div><div class=\"def\"><num0>Ⅰ</num0> (<i>intr</i>)叫ぶ, 歓喜の声をあげる.</div><div class=\"def\"><num0>Ⅱ</num0> (<i>tr</i>)大声で呼びかける.</div>\r\n","<div class=\"hw\">jūcunditās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[jucundus]</div><div class=\"def\"><num>①</num> 快いこと.</div><div class=\"def\"><num>②</num> 愛すべきこと, 感じのよさ;人気, 人望.</div><div class=\"def\"><num>③</num> (<i>pl</i>)親切な行為, 恩恵.</div>\r\n","<div class=\"hw\">jūcundor</div><div class=\"pos\">-ārī, <SUP>◇</SUP><i>intr dep</i></div><div class=\"ori\">[↑<a href=\"entry://jūcundō\">jūcundō</a>]</div><div class=\"def\">喜ぶ, 楽しむ.</div>\r\n","<div class=\"hw\">jūcundus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[jocus]</div><div class=\"def\"><num>①</num> 快い, 楽しい.</div><div class=\"def\"><num>②</num> 愛すべき, 感じのよい.</div>\r\n","<div class=\"hw\">jūcundē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[jucundus]</div><div class=\"def\">楽しく, 快く.</div>\r\n","<div class=\"hw\">jūcundō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>tr</i></div><div class=\"ori\">[jucundus]</div><div class=\"def\">楽しませる, 喜ばせる.</div>\r\n","<div class=\"hw\">Jūda</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i><<i>Heb</i>.]</div><div class=\"def\">〘聖〙ユダ《イスラエル民族の祖 Jacob の息子;イスラエル十二支族の一つの長》.</div>\r\n","<div class=\"hw\">Jūdaea</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i><<i>Heb</i>.]</div><div class=\"def\">ユーダエア,<SUP>*</SUP>-イアー, <SUP>∥</SUP>ユダヤ《Palaestina 南西部, ユダヤ人の国》.</div>\r\n","<div class=\"hw\">Jūdaeicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Jūdaicus\">Judaicus</a>.</div>\r\n","<div class=\"hw\">Jūdaeus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">ユダヤの, ユダヤ人の.</div><hr><div class=\"hw\">Jūdaeus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ユダヤ人.</div>\r\n","<div class=\"hw\">Jūdaicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">ユダヤの, ユダヤ人の.</div>\r\n","<div class=\"hw\">Jūdaicē</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://Jūdaicus\">Jūdaicus</a>]</div><div class=\"def\"><num>①</num> ユダヤ人のように.</div><div class=\"def\"><num>②</num> ヘブライ語で.</div>\r\n","<div class=\"hw\">jūdex</div><div class=\"pos\">jūdicis, <i>m(f)</i></div><div class=\"ori\">[judico]</div><div class=\"def\"><num>①</num> 審判者, 裁判官;陪審員.</div><div class=\"def\"><num>②</num> 判定者, 評価する人.</div>\r\n","<div class=\"hw\">jūdicium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[judex]</div><div class=\"def\"><num>①</num> 裁判, 審理 〈alcis rei;de re〉.</div><div class=\"def\"><num>②</num> 法廷.</div><div class=\"def\"><num>③</num> (総称的に)審判人団.</div><div class=\"def\"><num>④</num> 判決, 裁決.</div><div class=\"def\"><num>⑤</num> 裁判権, 司法権.</div><div class=\"def\"><num>⑥</num> 意見, 見解;判断, 評価.</div><div class=\"def\"><num>⑦</num> 尊重, 好意的評価.</div><div class=\"def\"><num>⑧</num> 判断力, 洞察力.</div>\r\n","<div class=\"hw\">jūdiciālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[judicium]</div><div class=\"def\">裁判の, 法廷の.</div>\r\n","<div class=\"hw\">jūdiciāliter</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://jūdiciālis\">jūdiciālis</a>]</div><div class=\"def\">裁判によって, 司法上.</div>\r\n","<div class=\"hw\">jūdiciārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://jūdiciālis\">judicialis</a>.</div>\r\n","<div class=\"hw\">jūdicātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[judico]</div><div class=\"def\"><num>①</num> 判決;判定.</div><div class=\"def\"><num>②</num> 〘修〙争点.</div><div class=\"def\"><num>③</num> 判断, 評価.</div>\r\n","<div class=\"hw\">jūdicātor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[judico]</div><div class=\"def\">判断[判定]者.</div>\r\n","<div class=\"hw\">jūdicātrix</div><div class=\"pos\">-īcis, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://jūdicātor\">jūdicātor</a>]</div><div class=\"def\">判断[判定]者《女性》.</div>\r\n","<div class=\"hw\">jūdicātum</div><div class=\"pos\">-ī, <i>n</i>(<i>pp</i>)</div><div class=\"ori\">[judico]</div><div class=\"def\">〘法〙</div><div class=\"def\"><num>①</num> 判決;判例.</div><div class=\"def\"><num>②</num> 判決債務.</div>\r\n","<div class=\"hw\">jūdicātus<SUP>1</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[judico]</div><div class=\"def\">判決債務者.</div><hr><div class=\"hw\">jūdicātus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"ori\">[judex]</div><div class=\"def\">審判者[陪審員]の職務.</div>\r\n","<div class=\"hw\">jūdicātō</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[judico]</div><div class=\"def\">熟慮して.</div>\r\n","<div class=\"hw\">jūdicō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i>, <i>intr</i></div><div class=\"ori\">[judex]</div><div class=\"def\"><num>①</num> 審判者である;裁く, 判決を下す 〈<i>abs</i>;de re;alqd;+<i>gen</i>〉.</div><div class=\"def\"><num>②</num> 決定する, 判断する 〈+<i>acc c. inf</i>;de re〉.</div><div class=\"def\"><num>③</num> 信ずる, 思う 〈de re;+<i>acc c.inf</i>〉.</div><div class=\"def\"><num>④</num> 評価する 〈de re〉.</div><div class=\"def\"><num>⑤</num> 宣言する 〈+2個の <i>acc</i>〉.</div>\r\n","<div class=\"hw\">jūgerum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>cf. </i> jugum]</div><div class=\"def\"><num>①</num> 地積単位《一くびきの牛が一日で耕しうる広さ;=約 <img class=\"font\" src=\"img/B153.png\"> ヘクタール》.</div><div class=\"def\"><num>②</num> (<i>pl</i>)広大な土地.</div>\r\n","<div class=\"hw\">jūgis<SUP>1</SUP></div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[jungo]</div><div class=\"def\">絶え間のない, とぎれない</div><div class=\"ex\"><i>～ aqua</i> (<author>S<small>ALL</small></author>)<span class=\"ext\">流水.</span></div>\r\n","<div class=\"hw\">jūgiter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[jugis<SUP>1</SUP>]</div><div class=\"def\">とぎれることなく, 連続して.</div>\r\n","<div class=\"hw\">jūgitās</div><div class=\"pos\">-ātis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[jugis<SUP>1</SUP>]</div><div class=\"def\">とぎれないこと, 継続.</div>\r\n","<div class=\"hw\">jūglans</div><div class=\"pos\">-andis, <i>f</i></div><div class=\"ori\">[Jovis/glans]</div><div class=\"def\">〘植〙クルミ(胡桃).</div>\r\n","<div class=\"hw\">Jūlia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ユーリア《 (1) Julius Caesar の娘で Cn. Pompeius の妻(前54没).(2) Augustus 帝の一人娘;Marcellus, Agrippa, Tiberius と次々に結婚;身持ちの悪さで有名(前39‐後14)》.</div>\r\n","<div class=\"hw\">Jūlius<SUP>1</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ユーリウス《ローマ人の氏族名;Caesar 家はこの氏族に属する》.</div><hr><div class=\"hw\">Jūlius<SUP>2</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> Julius の.</div><div class=\"def\"><num>②</num> 7月の.</div><hr><div class=\"hw\">Jūlius<SUP>3</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">7月《従来 Quintilis(第5月)と称したが, 前44年 Julius Caesar の出生月であるのにちなんで Julius と改称された》.</div>\r\n","<div class=\"hw\">Jūliānus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Julius Caesar の.</div><hr><div class=\"hw\">Jūliānus<SUP>2</SUP></div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"def\">ユーリアヌス《<i>Flavius Claudius ～</i>, ローマ皇帝(在位361‐363);キリスト教から異教に改宗したため Apostata(背教者)と呼ばれる》.</div>\r\n","<div class=\"hw\">Jūliānī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"ori\">[Julius]</div><div class=\"def\">(内乱時の)Caesar 側についた兵士たち.</div>\r\n","<div class=\"hw\">Jūlus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">〘伝説〙ユールス《Aeneas と Creusa の息子 Ascanius の別名;Julia 氏族の祖とされる》.</div>\r\n","<div class=\"hw\">Jūlēus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> Julus の(子孫の).</div><div class=\"def\"><num>②</num> Julia 氏族に属する.</div><div class=\"def\"><num>③</num> 6月の.</div>\r\n","<div class=\"hw\">jūmentum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[jungo]</div><div class=\"def\">荷物運搬用の動物, 役畜《ラバ・馬など》.</div>\r\n","<div class=\"hw\">jūnior</div><div class=\"pos\">-ior -ius, <i>adj comp</i></div><div class=\"def\">⇒<a href=\"entry://juvenis\">juvenis<SUP>1</SUP></a>.</div>\r\n","<div class=\"hw\">jūniperus</div><div class=\"pos\">-ī, <i>f</i></div><div class=\"def\">〘植〙ビャクシン.</div>\r\n","<div class=\"hw\">Jūnius<SUP>1</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ユーニウス《ローマ人の氏族名》.</div><hr><div class=\"hw\">Jūnius<SUP>2</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[Juno]</div><div class=\"def\">6月の</div><div class=\"ex\"><i>mensis ～</i> (<author>V<small>ARR</small></author>)<span class=\"ext\">6月.</span></div><hr><div class=\"hw\">Jūnius<SUP>3</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">6月.</div>\r\n","<div class=\"hw\">jūnix</div><div class=\"pos\">-īcis, <i>f</i></div><div class=\"ori\">[<i>cf</i>. juvenis]</div><div class=\"def\">若い雌牛.</div>\r\n","<div class=\"hw\">Jūniānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Junius の.</div>\r\n","<div class=\"hw\">Jūnō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"def\">〘神話〙ユーノー《Saturnus の娘で Juppiter の妻;女性・結婚の守護神;ギリシア神話の Hera に当たる》</div><div class=\"ex\"><i>～ inferna</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">=<a href=\"entry://Prōserpina\">Proserpina</a></span></div><div class=\"ex\"><i>urbs Junonis</i> (<author>O<small>V</small></author>)<span class=\"ext\">=<a href=\"entry://Argos\">Argos</a>.</span></div>\r\n","<div class=\"hw\">Jūnōnicola</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[Juno/colo<SUP>2</SUP>]</div><div class=\"def\">Juno の崇拝者.</div>\r\n","<div class=\"hw\">Jūnōnigena</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[Juno/gigno]</div><div class=\"def\">Juno の息子(=<a href=\"entry://Volcānus\">Volcanus</a>).</div>\r\n","<div class=\"hw\">Jūnōnius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Juno の.</div>\r\n","<div class=\"hw\">Jūnōnālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">Juno の.</div>\r\n","<div class=\"hw\">Jūra</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">ユーラ, <SUP>∥</SUP>ジュラ《Helvetia と Gallia の境をなす山脈》.</div>\r\n","<div class=\"hw\">jūre</div><div class=\"pos\"><i>adv</i>(<i>abl</i>)</div><div class=\"ori\">[jus<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> 合法的に.</div><div class=\"def\"><num>②</num> 正当に, 当然.</div>\r\n","<div class=\"hw\">jūreconsultus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">=<a href=\"entry://jūrisconsultus\">jurisconsultus</a>.</div>\r\n","<div class=\"hw\">jūridiciālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://jūridicus\">jūridicus<SUP>1</SUP></a>]</div><div class=\"def\">裁判[司法]の.</div>\r\n","<div class=\"hw\">jūridicus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[jus<SUP>2</SUP>/dico<SUP>2</SUP>]</div><div class=\"def\">裁判[司法]上の.</div><hr><div class=\"hw\">jūridicus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">審判者, 裁判官.</div>\r\n","<div class=\"hw\">jūrigō</div><div class=\"pos\">-āre, <i>intr(tr)</i></div><div class=\"def\">=<a href=\"entry://jurgō\">jurgo</a>.</div>\r\n","<div class=\"hw\">jūrisconsultus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[jus<SUP>2</SUP>/consulo]</div><div class=\"def\">法律家.</div>\r\n","<div class=\"hw\">jūrisdictiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[jus<SUP>2</SUP>/dictio]</div><div class=\"def\"><num>①</num> 司法, 裁判.</div><div class=\"def\"><num>②</num> 司法[裁判]権.</div>\r\n","<div class=\"hw\">jūrisdictiōnālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://jūrisdictiō\">jūrisdictiō</a>]</div><div class=\"def\">司法[裁判]権の.</div>\r\n","<div class=\"hw\">jūrisperītus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[jus<SUP>2</SUP>/peritus<SUP>2</SUP>]</div><div class=\"def\">法律家.</div>\r\n","<div class=\"hw\">jūrisprūdentia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[jus<SUP>2</SUP>/prudentia]</div><div class=\"def\">法学.</div>\r\n","<div class=\"hw\">jūror</div><div class=\"pos\">-ārī -ātus sum, <i>intr(tr)dep</i></div><div class=\"def\">=<a href=\"entry://jūrō\">juro</a>.</div>\r\n","<div class=\"hw\">jūrāmentum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[juro]</div><div class=\"def\">誓い, 誓約.</div>\r\n","<div class=\"hw\">jūrātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[juro]</div><div class=\"def\">宣誓.</div>\r\n","<div class=\"hw\">jūrātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[juro]</div><div class=\"def\"><num>①</num> 宣誓者, 宣誓した証人.</div><div class=\"def\"><num>②</num> 納税者の宣誓した申告を受ける租税査定官.</div>\r\n","<div class=\"hw\">jūrātus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[juro]</div><div class=\"def\">誓約した, 宣誓した.</div>\r\n","<div class=\"hw\">jūrātō</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i>(<i>abl</i>)</div><div class=\"ori\">[juratus]</div><div class=\"def\">宣誓して, 誓約して.</div>\r\n","<div class=\"hw\">jūrō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i>(<i>tr</i>)</div><div class=\"ori\">[jus<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> 誓う, 誓約する</div><div class=\"ex\"><i>per deos jurare</i> (<author>C<small>IC</small></author>)<span class=\"ext\">神々にかけて誓う</span></div><div class=\"ex\"><i>in legem jurare</i> (<author>C<small>IC</small></author>)<span class=\"ext\">法の遒守を誓う</span></div><div class=\"ex\"><i>in verba alcis jurare</i> (<author>S<small>UET</small></author>)<span class=\"ext\">(兵士たちが)ある人に忠誠を誓う.</span></div><div class=\"def\"><num>②</num> 誓って保証[断言]する 〈alqd;+<i>inf</i>;+<i>acc c. inf</i>〉</div><div class=\"ex\"><i>qui sine hac jurabat se unum numquam victurum diem?</i> (<author>T<small>ER</small></author>)<span class=\"ext\">彼女なしには一日だって生きていけないと誓ったのは誰かしら.</span></div><div class=\"def\"><num>③</num> 共謀する</div><div class=\"ex\"><i>in me jurarunt somnus ventusque</i> (<author>O<small>V</small></author>)<span class=\"ext\">眠りと風とが私の破滅を謀った.</span></div><div class=\"def\"><num>④</num> 〘法〙</div><div class=\"ex\"><i>calumniam jurare</i> (<author>C<small>IC</small></author>)<span class=\"ext\">善意による告発であることを宣誓する.</span></div>\r\n","<div class=\"hw\">jūs<SUP>1</SUP></div><div class=\"pos\">jūris, <i>n</i></div><div class=\"def\">スープ, 煮出し汁.</div><hr><div class=\"hw\">jūs<SUP>2</SUP></div><div class=\"pos\">jūris, <i>n</i></div><div class=\"ori\">[<i>cf. </i> jubeo]</div><div class=\"def\"><num>①</num> 法, 法律</div><div class=\"ex\"><i>～ civile</i> (<author>C<small>IC</small></author>)<span class=\"ext\">市民法《ローマ市民の法》</span></div><div class=\"ex\"><i>～ gentium</i> (<author>C<small>IC</small></author>)<span class=\"ext\">万民法《ローマ市民と外国人に等しく適用される法》</span></div><div class=\"ex\"><i>～ naturale</i> (<author>C<small>IC</small></author>)<span class=\"ext\">自然法《自然によって人間に生まれつき与えられている理想的な法》.</span></div><div class=\"def\"><num>②</num> 権利, 特権.</div><div class=\"def\"><num>③</num> 司法権, 支配権.</div><div class=\"def\"><num>④</num> 法廷.</div><div class=\"def\"><num>⑤</num> 正当, 公正.</div>\r\n","<div class=\"hw\">jūsum</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"def\">下方へ.</div>\r\n","<div class=\"hw\">Jūturna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">〘神話〙ユートゥルナ《泉のニンフ;Rutuli 族の王 Turnus の姉妹ともされる》.</div>\r\n","<div class=\"hw\">jūtus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://juvō\">juvo</a>.</div>\r\n","<div class=\"hw\">jūvī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://juvō\">juvo</a>.</div>\r\n"]);
